\"\"\"Minimal OpenAI Responses API client using only the standard library.

The API key is read from the OPENAI_API_KEY environment variable (or passed
explicitly). Prompts are sent with "'``store=False`` so OpenAI does not retain
the response, and prompts/keys are never logged or written to disk.
"""

import json
import os
import sys
import urllib.error
import urllib.request

API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4o-mini"


class OpenAIError(Exception):
    """Raised when the API returns an error or an unusable response."""


def extract_text(response):
    """Return the concatenated output text from a Responses API payload."""
    if isinstance(response.get("output_text"), str):
        return response["output_text"]
    parts = []
    for item in response.get("output", []):
        if item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "".join(parts)


def send_prompt(
    prompt,
    model=DEFAULT_MODEL,
    api_key=None,
    instructions=None,
    store=False,
    timeout=60,
    **extra,
):
    """Send a text prompt and return the full response as a dict.

    ``store`` defaults to False so the response is not retained by OpenAI.
    Additional keyword arguments are passed through in the request body.
    """
    api_key = api_key or os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise OpenAIError("Set OPENAI_API_KEY or pass api_key=")

    body = {"model": model, "input": prompt, "store": store}
    if instructions:
        body["instructions"] = instructions
    body.update(extra)

    request = urllib.request.Request(
        API_URL,
        data=json.dumps(body).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as reply:
            return json.loads(reply.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        detail = error.read().decode("utf-8", errors="replace")
        try:
            detail = json.loads(detail)["error"]["message"]
        except (ValueError, KeyError, TypeError):
            pass
        raise OpenAIError("HTTP %d: %s" % (error.code, detail)) from None
    except urllib.error.URLError as error:
        raise OpenAIError("Connection failed: %s" % error.reason) from None


def ask(prompt, **kwargs):
    """Send a prompt and return just the response text."""
    return extract_text(send_prompt(prompt, **kwargs))


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    prompt = " ".join(argv) if argv else sys.stdin.read()
    if not prompt.strip():
        print("usage: openai_client.py [prompt]   (or pipe prompt on stdin)", file=sys.stderr)
        return 2
    try:
        print(ask(prompt))
    except OpenAIError as error:
        print("error: %s" % error, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
